  "Mkt3L10n.DataFormPanel.This_option_allows_control_how_filters_separated": "||_<p>This option allows you to control how filters are used. Only filters are affected&mdash;any triggers will apply separately.</p><p>Enter the filter numbers separated by \"and\" and \"or\".</p><ul><li>1 and 2 and 3</li><li>1 or 2 or 3</li></ul><p>Mixing \"and\" and \"or\" requires parenthesis so that your intention is clear. For example, \"1 or 2 and 3\" must be written as one of the following:</p><ul><li>1 and (2 or 3)</li><li>(1 and 2) or 3</li></ul><p>More complicated logic may require nested parenthesis.</p><ul><li>(1 and 2) or (3 and 4)</li><li>1 and (2 or (3 and 4))</li></ul><br /><p><img src=\"/images/icons16/sign_warning.png\" class=\"mki16-p\" /> Check your rules after any insert, delete, or reorder.</p>_||",
